(()=>{'use strict';const form=document.getElementById('handoff'),status=document.getElementById('status'),link=document.getElementById('open-chat');form.addEventListener('submit',async event=>{event.preventDefault();link.hidden=true;status.textContent='Preparing message…';try{const response=await fetch('/api/whatsapp/handoff',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({phone:document.getElementById('phone').value,message:document.getElementById('message').value,consent:document.getElementById('consent').checked})});const data=await response.json();if(!response.ok)throw Error(data.error||'Could not prepare message');link.href=data.url;link.hidden=false;status.textContent='Ready. Opening WhatsApp is a separate action; no message has been sent.';}catch(error){status.textContent=error.message;}});})();